"use client";
import { motion } from "framer-motion";

export default function Hero({ person }: { person: any }) {
    return (
        <section className="min-h-screen flex flex-col justify-center items-center text-center px-6 pt-20">
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8, ease: [0.22, 0.61, 0.36, 1] }}
                className="max-w-4xl"
            >
                <motion.span
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 0.2 }}
                    className="text-accent font-mono text-[10px] md:text-xs uppercase tracking-[0.3em] font-bold mb-6 block"
                >
                    Product Designer • {person.location}
                </motion.span>

                <h1 className="text-5xl md:text-[5rem] lg:text-[6.5rem] font-bold tracking-tighter leading-[0.95] text-foreground mb-10">
                    Crafting <span className="italic">Experiences</span>,<br />
                    One Pixel at a Time.
                </h1>

                <p className="text-lg md:text-xl text-subtext font-light max-w-xl mx-auto leading-relaxed mb-12">
                    Hi, I’m a product designer who transforms complex ideas into seamless, user-centered solutions.
                </p>

                <div className="flex flex-col sm:flex-row gap-4 justify-center">
                    <a
                        href="#work"
                        className="px-10 py-4 bg-foreground text-background font-semibold rounded-full hover:scale-105 transition-transform duration-300 shadow-xl shadow-black/5"
                    >
                        View Work
                    </a>
                    <a
                        href="mailto:manovenkat06@gmail.com"
                        className="px-10 py-4 border-2 border-foreground/5 text-foreground font-semibold rounded-full hover:border-foreground/10 transition-all duration-300"
                    >
                        Get in Touch
                    </a>
                </div>
            </motion.div>
        </section>
    );
}
