"use client";
import { motion } from "framer-motion";

export default function Marquee({ items }: { items: string[] }) {
    return (
        <div className="relative flex overflow-hidden py-12 border-y border-foreground/[0.03]">
            <motion.div
                animate={{ x: ["0%", "-50%"] }}
                transition={{ repeat: Infinity, duration: 25, ease: "linear" }}
                className="flex whitespace-nowrap"
            >
                {[...items, ...items].map((item, i) => (
                    <span key={i} className="mx-8 text-4xl md:text-6xl font-bold tracking-tighter stroke-text uppercase">
                        {item}
                    </span>
                ))}
            </motion.div>
        </div>
    );
}
