"use client";
import { motion } from "framer-motion";
import Image from "next/image";
import { ArrowUpRight } from "lucide-react";

export default function ProjectCard({ project, index }: { project: any, index: number }) {
    return (
        <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: "-100px" }}
            transition={{ duration: 0.6, ease: [0.22, 0.61, 0.36, 1] }}
            className="group block"
        >
            <div className="relative aspect-[16/10] overflow-hidden rounded-3xl bg-[#F5F5F5] mb-8">
                <Image
                    src={project.image}
                    alt={project.title}
                    fill
                    className="object-cover group-hover:scale-105 transition-transform duration-700"
                />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 transition-colors duration-500" />
            </div>

            <div className="flex justify-between items-start px-2">
                <div className="space-y-1">
                    <div className="flex items-center gap-2">
                        <span className="text-[10px] font-bold uppercase tracking-wider text-accent">{project.role}</span>
                    </div>
                    <h3 className="text-2xl md:text-3xl font-bold tracking-tight text-foreground">{project.title}</h3>
                </div>
                <div className="w-12 h-12 rounded-full border border-foreground/5 flex items-center justify-center group-hover:bg-foreground group-hover:text-background transition-all duration-300">
                    <ArrowUpRight className="w-5 h-5" />
                </div>
            </div>
        </motion.div>
    );
}
