"use client";

import Navbar from "@/components/Navbar";
import Hero from "@/components/Hero";
import ProjectCard from "@/components/ProjectCard";
import Marquee from "@/components/Marquee";
import { PERSON } from "@/lib/data";
import { motion } from "framer-motion";
import { CheckCircle2, ChevronRight } from "lucide-react";

export default function Home() {
    const skills = [...PERSON.skills.technical, ...PERSON.skills.tools];

    return (
        <main className="relative selection:bg-accent/20">
            <Navbar />

            <Hero person={PERSON} />

            <Marquee items={skills} />

            {/* WORK SECTION */}
            <section id="work" className="section-gap px-6 md:px-12 max-w-7xl mx-auto">
                <div className="flex flex-col md:flex-row justify-between items-baseline mb-16 md:mb-24 gap-6">
                    <h2 className="text-4xl md:text-6xl font-bold tracking-tighter">Selected Works.</h2>
                    <p className="text-subtext max-w-sm text-lg font-light leading-relaxed">
                        A collection of projects showcasing visual precision and agentic design thinking.
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-24 md:gap-y-32">
                    {PERSON.projects.map((project, idx) => (
                        <ProjectCard key={idx} project={project} index={idx} />
                    ))}
                </div>
            </section>

            {/* SERVICES SECTION */}
            <section id="services" className="section-gap bg-[#F9F9F9] py-24 md:py-32">
                <div className="px-6 md:px-12 max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-16 md:gap-32">
                    <div>
                        <h2 className="text-4xl md:text-5xl font-bold tracking-tighter mb-8">Tailored Design Solutions.</h2>
                        <p className="text-subtext text-lg font-light leading-relaxed mb-10">
                            I help startups and enterprises build intelligent products through research, strategy, and execution.
                        </p>
                        <ul className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            {PERSON.skills.technical.map((skill, i) => (
                                <li key={i} className="flex items-center gap-2 text-foreground font-medium">
                                    <CheckCircle2 className="w-4 h-4 text-accent" />
                                    {skill}
                                </li>
                            ))}
                        </ul>
                    </div>
                    <div className="grid grid-cols-1 gap-8">
                        {/* Process blocks */}
                        {[
                            { step: "01", title: "Discover", desc: "Understanding goals through UX research and intent analysis." },
                            { step: "02", title: "Ideate", desc: "Exploring concepts, wireframing, and defining agentic flows." },
                            { step: "03", title: "Design", desc: "Crafting visually precise, scalable design systems." },
                            { step: "04", title: "Test", desc: "Validating through user testing and iterative refinement." },
                        ].map((p, i) => (
                            <div key={i} className="flex gap-6 group">
                                <span className="text-muted font-bold tracking-tighter text-xl mt-1">{p.step}</span>
                                <div>
                                    <h3 className="text-xl font-bold mb-2 group-hover:text-accent transition-colors">{p.title}</h3>
                                    <p className="text-subtext text-sm leading-relaxed">{p.desc}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* EXPERIENCE SECTION */}
            <section id="experience" className="section-gap px-6 md:px-12 max-w-5xl mx-auto">
                <h2 className="text-3xl font-bold tracking-tighter mb-16 underline decoration-accent decoration-4 underline-offset-8">Experience</h2>
                <div className="space-y-16">
                    {PERSON.experience.map((job, idx) => (
                        <div key={idx} className="flex flex-col md:flex-row gap-8 justify-between">
                            <div className="md:w-1/3">
                                <h3 className="text-xl font-bold">{job.company}</h3>
                                <p className="text-muted font-mono text-xs mt-2 uppercase tracking-widest">{job.period}</p>
                            </div>
                            <div className="md:w-2/3">
                                <h4 className="text-xl font-medium text-foreground mb-4">{job.role}</h4>
                                <p className="text-subtext text-sm leading-relaxed mb-6 italic">{job.description}</p>
                                <ul className="space-y-3">
                                    {job.achievements.map((item, i) => (
                                        <li key={i} className="text-[14px] text-subtext flex gap-2">
                                            <span className="text-accent">•</span>
                                            {item}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    ))}
                </div>
            </section>

            <footer id="about" className="section-gap pt-32 pb-20 px-6 text-center bg-foreground text-background">
                <div className="max-w-4xl mx-auto">
                    <h2 className="text-4xl md:text-7xl font-bold tracking-tighter mb-12">Let’s build something amazing together.</h2>
                    <a
                        href={`mailto:${PERSON.contact.email}`}
                        className="text-2xl md:text-3xl font-medium border-b-2 border-accent hover:text-accent transition-all duration-300 pb-2"
                    >
                        {PERSON.contact.email}
                    </a>

                    <div className="flex justify-center gap-10 mt-24 text-muted text-sm uppercase tracking-widest font-bold">
                        <a href={PERSON.contact.linkedin} target="_blank" className="hover:text-accent transition-colors">LinkedIn</a>
                        <a href="#" className="hover:text-accent transition-colors">Twitter (X)</a>
                        <a href="#" className="hover:text-accent transition-colors">Dribbble</a>
                    </div>

                    <p className="mt-32 text-muted/50 text-[10px] uppercase tracking-widest leading-loose">
                        © {new Date().getFullYear()} Manobala MVJ • Crafted with precision and intention.
                    </p>
                </div>
            </footer>
        </main>
    );
}
