"use client";
import { motion, useScroll, useTransform } from "framer-motion";
import Link from "next/link";

export default function Navbar() {
    const { scrollY } = useScroll();
    const backgroundColor = useTransform(scrollY, [0, 50], ["rgba(255, 255, 255, 0)", "rgba(255, 255, 255, 0.8)"]);
    const borderOpacity = useTransform(scrollY, [0, 50], ["rgba(0,0,0,0)", "rgba(0,0,0,0.05)"]);
    const filter = useTransform(scrollY, [0, 50], ["blur(0px)", "blur(12px)"]);

    return (
        <motion.nav
            style={{
                backgroundColor,
                borderColor: borderOpacity,
                backdropFilter: filter, // filter doesn't work directly for backdrop in motion style sometimes, use plain style or better props
                WebkitBackdropFilter: filter
            } as any}
            className="fixed top-0 left-0 right-0 z-50 px-6 py-4 md:px-12 md:py-6 border-b transition-all duration-300"
        >
            <div className="max-w-7xl mx-auto flex justify-between items-center">
                <Link href="/" className="text-xl font-bold tracking-tighter text-foreground">
                    M.
                </Link>
                <div className="flex gap-8 text-sm font-medium">
                    <Link href="#work" className="text-subtext hover:text-foreground hover:underline decoration-accent underline-offset-4 transition-all">Work</Link>
                    <Link href="#services" className="text-subtext hover:text-foreground hover:underline decoration-accent underline-offset-4 transition-all">Services</Link>
                    <Link href="#about" className="text-subtext hover:text-foreground hover:underline decoration-accent underline-offset-4 transition-all">About</Link>
                    <Link href="mailto:manovenkat06@gmail.com" className="text-foreground hover:text-accent transition-colors">Contact</Link>
                </div>
            </div>
        </motion.nav>
    );
}
